; hero.asm -- chapter 27: one sprite kept, seven turned
; generated by gen27.py
        INCLUDE "msx.inc"
        OUTPUT "hero.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; A dark blue ball, sprite 0, and seven figures on lines 88 to 103: the
; ball first in every table, the figures turned behind it, for 42 frames by
; 1 entry, then for 42 by 3. Three places are left for seven figures.
copy    EQU $C400               ; the figures twice ($D0 sent once)
step    EQU VARS                ; 4 x the entries to turn by
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the picture is drawn
        VDP_REG 0, $02          ; Graphic II: 256 x 192 pixels (chapter 22)
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $FF          ; colours            $2000, 6,144 bytes
        VDP_REG 4, $03          ; patterns           $0000, 6,144 bytes
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: every pixel paper
        ld bc, 6144
g2p:    xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2p
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld bc, 6144
g2c:    ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2c
        VRAM_WRITE $1800        ; names: 0 to 255 in each third
        ld b, 3
g2n:    xor a
g2n1:   out (VDP_DATA), a
        inc a
        jr nz, g2n1
        djnz g2n
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VRAM_WRITE $3800        ; the sprite patterns
        ld hl, patterns
        ld c, VDP_DATA
        ld b, 160
        otir
        ld hl, atts + 4         ; the copy: the seven figures twice
        ld de, copy
        ld bc, 28
        ldir
        ld hl, atts + 4
        ld bc, 28
        ldir
        VRAM_WRITE $1B00        ; the attributes
        ld hl, atts
        ld c, VDP_DATA
        ld b, 33
        otir
        VDP_REG 1, $C2          ; the display on, sprites of 16 x 16
        in a, (VDP_CTRL)        ; F cleared: the first wait ends with a paper
        ld d, 0                 ; k, times 4: the first figure sent
        ld a, 4                 ; by 1 entry
        ld (step), a
        ld e, 42
        call turns
        ld a, 12                ; by 3 entries
        ld (step), a
        ld e, 42
        call turns
done:   jr done

; turns: E frames, each the ball and the figures from entry k, k going up by
; step / 4 entries, round 7
turns:  ld a, (step)            ; 14
        add a, d                ;  5
        cp 28                   ;  8
        jr c, round             ; 13, or 8
        sub 28                  ;  8
round:  ld d, a                 ;  5
        call frame              ; the paper has ended
m0:     VRAM_WRITE $1B00        ; 40
        ld hl, atts             ; 11  the ball, from the cartridge
        ld c, VDP_DATA          ;  8
        ld b, 4                 ;  8
        otir                    ; 23 a byte, 18 the last
        ld hl, copy             ; 11  the figures, from entry k
        ld c, d                 ;  5  B is 0: OTIR left it so
        add hl, bc              ; 12
        ld c, VDP_DATA          ;  8
        ld b, 28                ;  8  seven entries
        otir                    ; 23 a byte, 18 the last
m1:     dec e
        jr nz, turns
        ret

; frame: wait for the end of the paper: F, bit 7 of the status, read with the
; interrupts off (chapter 19)
frame:  in a, (VDP_CTRL)
        rla
        jr nc, frame
        ret
patterns:
        db $03, $07, $05, $07, $02, $1F, $3F, $37
        db $37, $37, $07, $06, $06, $06, $0E, $0E
        db $C0, $E0, $A0, $E0, $40, $F8, $FC, $EC
        db $EC, $EC, $E0, $60, $60, $60, $70, $70
        db $00, $07, $0F, $1F, $3F, $7F, $7F, $7F
        db $7F, $7F, $7F, $3F, $1F, $0F, $07, $00
        db $00, $E0, $F0, $F8, $FC, $FE, $FE, $FE
        db $FE, $FE, $FE, $FC, $F8, $F0, $E0, $00
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        db $07, $18, $20, $40, $46, $86, $80, $80
        db $80, $88, $47, $40, $20, $18, $07, $00
        db $E0, $18, $04, $02, $62, $61, $01, $01
        db $01, $11, $E2, $02, $04, $18, $E0, $00
        db $00, $07, $1F, $3F, $39, $79, $7F, $7F
        db $7F, $77, $38, $3F, $1F, $07, $00, $00
        db $00, $E0, $F8, $FC, $9C, $9E, $FE, $FE
        db $FE, $EE, $1C, $FC, $F8, $E0, $00, $00
atts:
        db $57, $08, $04, $04
        db $57, $26, $00, $01
        db $57, $44, $00, $01
        db $57, $62, $00, $01
        db $57, $80, $00, $01
        db $57, $9E, $00, $01
        db $57, $BC, $00, $01
        db $57, $DA, $00, $01
        db $D0
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
